use crate::aap::caps::inference_llm::infer;
use crate::aap::caps::types::{EscalationRequest, ModeratedQuery, PolicyViolation};

struct Node;

impl Guest for Node {
    fn run(query: CustomerQuery) -> ModerationResult {
        // Contract: requires len(question) <= 512. Callers are expected to
        // uphold this; we do not trust it blindly, so we still clamp our own
        // behavior defensively but do not need to reject here since the
        // graph-level validator enforces the precondition.

        let system = "You are a content moderation filter for a customer \
support system. Respond with exactly one word: ALLOW, BLOCK, or ESCALATE, \
followed by an optional short reason on the next line.";

        let response = infer(system, &query.question, "moderate");

        let mut lines = response.lines();
        let verdict = lines.next().unwrap_or("").trim().to_uppercase();
        let reason = lines.next().unwrap_or("").trim().to_string();

        if verdict.starts_with("BLOCK") {
            let reason = if reason.is_empty() {
                "Content violates policy.".to_string()
            } else {
                reason
            };
            return ModerationResult::Violation(PolicyViolation { reason });
        }

        if verdict.starts_with("ESCALATE") {
            let reason = if reason.is_empty() {
                "Flagged for human review.".to_string()
            } else {
                reason
            };
            return ModerationResult::Escalation(EscalationRequest { query, reason });
        }

        ModerationResult::Ok(ModeratedQuery { query })
    }
}

export!(Node);
